frappe.ui.form.on('Employee', {

    onload(frm) {
        set_vendor_editable(frm);
    },

    refresh(frm) {
        frm.toggle_display(
            'vendor',
            frm.doc.custom_employee_type === 'Vendor'
        );

        set_vendor_editable(frm);
    },

    custom_employee_type(frm) {

        if (frm.doc.custom_employee_type === 'Vendor') {

            frm.toggle_display('vendor', true);
            set_vendor_editable(frm);

        } else {

            frm.toggle_display('vendor', false);

            frm.set_value('vendor', '');

            // Do not modify Company for Direct or empty type
        }
    },

    vendor(frm) {

        if (frm.doc.custom_employee_type !== 'Vendor') {
            return;
        }

        const selected_vendor = frm.doc.vendor;

        // Allow Vendor to be changed at any time
        set_vendor_editable(frm);

        if (!selected_vendor) {
            frm.set_value('company', '');
            return;
        }

        // Track the latest selection
        frm.__vendor_lookup_id = (frm.__vendor_lookup_id || 0) + 1;

        const lookup_id = frm.__vendor_lookup_id;

        frappe.db.get_list('Company', {
            filters: {
                supplier: selected_vendor
            },
            fields: ['name'],
            limit: 2
        }).then(records => {

            // Ignore previous lookup responses
            if (lookup_id !== frm.__vendor_lookup_id) {
                return;
            }

            if (
                frm.doc.custom_employee_type !== 'Vendor' ||
                frm.doc.vendor !== selected_vendor
            ) {
                return;
            }

            if (records.length === 1) {

                // Replace the previous Company automatically
                frm.set_value('company', records[0].name);

            } else {

                frm.set_value('company', '');

                if (records.length === 0) {

                    frappe.msgprint(
                        __('No Company found for Supplier: {0}', [
                            selected_vendor
                        ])
                    );

                } else {

                    frappe.msgprint(
                        __('Multiple Companies found for Supplier: {0}', [
                            selected_vendor
                        ])
                    );
                }
            }

            set_vendor_editable(frm);
        });
    },

    company(frm) {

        // Keep Vendor editable even after Company is populated
        if (frm.doc.custom_employee_type === 'Vendor') {
            set_vendor_editable(frm);
        }
    }
});


// Force Vendor field to remain editable
function set_vendor_editable(frm) {

    if (!frm.fields_dict.vendor) {
        return;
    }

    frm.set_df_property('vendor', 'read_only', 0);

    // Remove conditional read-only dependency
    frm.set_df_property('vendor', 'read_only_depends_on', '');

    frm.toggle_enable('vendor', true);

    frm.refresh_field('vendor');
}

